## Code Example
```javascript
function maxWorkload(workload, k) {
  const n = workload.length;
  const NEG = -1e15;
  const noBoost = Array.from({ length: n }, () => Array(k+1).fill(NEG));
  const boost = Array.from({ length: n }, () => Array(k+1).fill(NEG));
  noBoost[0][0] = workload[0];
  if (k >= 1) boost[0][1] = 2 * workload[0];
  for (let i = 1; i < n; i++) {
    for (let t = 0; t <= k; t++) {
      noBoost[i][t] = Math.max(noBoost[i-1][t], boost[i-1][t]) + workload[i];
    }
    for (let t = 1; t <= k; t++) {
      if (noBoost[i-1][t-1] > NEG) boost[i][t] = noBoost[i-1][t-1] + 2*workload[i];
    }
  }
  let best = NEG, bestT = 0, bestS = 0;
  for (let t = 0; t <= k; t++) {
    if (noBoost[n-1][t] > best) { best = noBoost[n-1][t]; bestT = t; bestS = 0; }
    if (boost[n-1][t] > best) { best = boost[n-1][t]; bestT = t; bestS = 1; }
  }
  // reconstruction would backtrack using saved states (omitted for brevity)
  return { maxValue: best, boostedIndices: [] };
}
```

## Why This Is Asked

Tests dynamic programming on partitioning a string into numeric substrings, including numeric parsing and reconstruction, a common interview pattern.

## Key Concepts

- DP on string partitions with exact k blocks
- Efficient substring value computation and leading-zero handling
- Path reconstruction via parent pointers
- Time/space trade-offs: O(n^2 k) time, O(nk) space

## Code Example

```javascript
function maxSumPartition(s, k) {
  const n = s.length;
  // val[i][j] = value of s[i..j-1]
  const val = Array.from({ length: n+1 }, () => Array(n+1).fill(0));
  for (let i = 0; i < n; i++) {
    if (s[i] === '0') { val[i][i+1] = 0; continue; }
    let cur = 0;
    for (let j = i; j < n; j++) {
      cur = cur*10 + (s.charCodeAt(j) - 48);
      val[i][j+1] = cur;
    }
  }
  const dp = Array.from({ length: n+1 }, () => Array(k+1).fill(-Infinity));
  const par = Array.from({ length: n+1 }, () => Array(k+1).fill(-1));
  for (let i = 1; i <= n; i++) dp[i][1] = val[0][i];
  for (let t = 2; t <= k; t++) {
    for (let i = t; i <= n; i++) {
      for (let j = t-1; j < i; j++) {
        if (s[j] === '0' && i - j > 1) continue;
        const cand = dp[j][t-1] + val[j][i];
        if (cand > dp[i][t]) { dp[i][t] = cand; par[i][t] = j; }
      }
    }
  }
  // reconstruct cuts
  const cuts = [];
  let i = n, t = k;
  while (t > 0) {
    const j = par[i][t];
    cuts.push(i);
    i = j;
    t--;
  }
  cuts.push(0);
  cuts.reverse();
  return { sum: dp[n][k], cuts };
}
```

