function maxKSubarraysMin(A, k) {
  const n = A.length;

  // Precompute range minima
  const mins = Array.from({length: n}, () => Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    let m = Infinity;
    for (let j = i; j < n; j++) {
      m = Math.min(m, A[j]);
      mins[i][j] = m;
    }
  }
```

## Why This Is Asked
This problem tests understanding of partition dynamic programming with nontrivial segment costs, requiring careful recurrence formulation, efficient range query handling, and solution reconstruction.

## Key Concepts
- Partition DP with fixed number of contiguous segments
- Segment cost computation using range max-min queries
- Reconstruction via predecessor pointers
- Time/space optimization techniques

## Code Example
```javascript
function minCostPartitions(A, k) {
  const n = A.length;
  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(Infinity));
  const pre = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-1));

  dp[0][0] = 0;

  // Base case: single segment
  for (let i = 1; i <= n; i++) {
    let maxVal = A[0], minVal = A[0];
    for (let j = 0; j < i; j++) {
      maxVal = Math.max(maxVal, A[j]);
      minVal = Math.min(minVal, A[j]);
      dp[i][1] = maxVal - minVal;
    }
  }

  // DP transitions
  for (let t = 2; t <= k; t++) {
    for (let i = 1; i <= n; i++) {
      for (let j = t - 1; j < i; j++) {
        const segmentCost = computeCost(A, j + 1, i);
        if (dp[j][t - 1] + segmentCost < dp[i][t]) {
          dp[i][t] = dp[j][t - 1] + segmentCost;
          pre[i][t] = j;
        }
      }
    }
  }

  // Reconstruct segments
  const segments = [];
  let end = n;
  for (let t = k; t >= 1; t--) {
    const start = pre[end][t] + 1;
    segments.unshift([start, end]);
    end = pre[end][t];
  }

  return { minCost: dp[n][k], segments };
}
```

## Why This Is Asked
Tests budgeted DP on strings and reconstruction. 

## Key Concepts
- dp[i][j][d] encodes a subproblem under a deletion budget; 
- palindrome subsequence logic with matches/skips; 
- reconstruction paths under deletion budget.

## Code Example
```javascript
function maxPalWithDeletions(s, k){
  const n=s.length; 
  const dp=Array.from({length:n},()=>Array.from({length:n},()=>Array(k+1).fill(0)));
  for(let i=0;i<n;i++){ dp[i][i][0]=1; for(let d=1; d<=k; d++) dp[i][i][d]=1; }
  for(let len=2; len<=n; len++){
    for(let i=0; i+len-1<n; i++){
      const j=i+len-1;
      for(let d=0; d<=k; d++){
        if(s[i]===s[j]){
          dp[i][j][d]=Math.max(dp[i+1][j-1][d]+2, (d>0?dp[i+1][j][d-1]:0), (d>0?dp[i][j-1][d-1]:0));
        } else {
          dp[i][j][d]=Math.max(dp[i+1][j][d], dp[i][j-1][d], (d>0?dp[i+1][j-1][d-1]:0));
        }
      }
    }
  }
  return Math.max(...Array.from({length:k+1},(_,d)=>dp[0][n-1][d]));
}
```

